sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {

    // Add your code here
    var insu = new InsuranceUtils()

    var insurance = insu.fetchinsurancedetailpatientid('PAT0001093');
    if (insurance.next()) {
        gs.print('Insurance ID: ' + insurance.number);
        gs.print("Status: " + insurance.u_status);
        gs.print("Covers: " + insurance.u_coverage_details);
        gs.print("-----------")
    } else {
        gs.print("NO Record")
    }

    var active = insu.checkactive('INS0001028');
    gs.print("Status is Active: " + active);
    gs.print("-----------------")

    var fetchbyinsid = insu.fetchdetails('INS0001028')
    while (fetchbyinsid.next()) {
        gs.print("Insurance ID: " + fetchbyinsid.number.getDisplayValue());
        gs.print("PAtient ID: " + fetchbyinsid.u_patient_id.getDisplayValue());
        gs.print("Covers: " + fetchbyinsid.u_coverage_details);
        gs.print("Status: " + fetchbyinsid.u_status);
        //gs.print("-----------")

    }

    var byprovider = insu.fetchbyprovider('Star Health');
    gs.print("---Through Provider----")
    var count = 0;
    while (byprovider.next()) {
        gs.print("Count Number: " + count);
        gs.print("Insurance ID: " + byprovider.number.getDisplayValue());
        gs.print("PAtient ID: " + byprovider.u_patient_id.getDisplayValue());
        gs.print("Covers: " + byprovider.u_coverage_details);
        gs.print("Status: " + byprovider.u_status);
        gs.print("-----------")
        count += 1;
    }

})(current, previous);
